// Simple regex parsing to add/adjust SVG attributes
// Written by AI.
export function naiveParser(content, options) {
  const { class: klass, width, height, attributes = {}, ...rest } = options

  // Parse the opening <svg> tag
  const svgMatch = content.match(/<svg[^>]*>/i)
  if (!svgMatch) return content

  let svgTag = svgMatch[0]

  // Extract existing attributes
  const existingWidth = svgTag.match(/width="([^"]*)"/)
  const existingHeight = svgTag.match(/height="([^"]*)"/)
  const existingViewBox = svgTag.match(/viewBox="([^"]*)"/)

  // Parse values
  const currentWidth = existingWidth ? existingWidth[1] : null
  const currentHeight = existingHeight ? existingHeight[1] : null
  const currentViewBox = existingViewBox ? existingViewBox[1] : null

  // Add class if provided
  if (klass) {
    if (svgTag.includes('class=')) {
      // Add to existing class
      svgTag = svgTag.replace(/class="([^"]*)"/, `class="$1 ${klass}"`)
    } else {
      // Add new class attribute
      svgTag = svgTag.replace('>', ` class="${klass}">`)
    }
  }

  // Handle width/height and viewBox relationship
  let finalWidth = width || currentWidth
  let finalHeight = height || currentHeight
  let finalViewBox = currentViewBox

  // If viewBox exists but width/height don't, extract from viewBox
  if (currentViewBox && (!currentWidth || !currentHeight)) {
    const viewBoxValues = currentViewBox.split(/\s+/)
    if (viewBoxValues.length === 4) {
      const [, , vbWidth, vbHeight] = viewBoxValues
      if (!currentWidth && !width) finalWidth = vbWidth
      if (!currentHeight && !height) finalHeight = vbHeight
    }
  }

  // If width/height exist but viewBox doesn't, create viewBox
  // from the file's own dimensions — a width/height option only
  // changes the display size, not the coordinate system.
  if (!currentViewBox && currentWidth && currentHeight) {
    finalViewBox = `0 0 ${currentWidth} ${currentHeight}`
  }

  // Apply width if we have a final value
  if (finalWidth) {
    if (svgTag.includes('width=')) {
      svgTag = svgTag.replace(/width="[^"]*"/, `width="${finalWidth}"`)
    } else {
      svgTag = svgTag.replace('>', ` width="${finalWidth}">`)
    }
  }

  // Apply height if we have a final value
  if (finalHeight) {
    if (svgTag.includes('height=')) {
      svgTag = svgTag.replace(/height="[^"]*"/, `height="${finalHeight}"`)
    } else {
      svgTag = svgTag.replace('>', ` height="${finalHeight}">`)
    }
  }

  // Apply viewBox if we have a final value
  if (finalViewBox) {
    if (svgTag.includes('viewBox=')) {
      svgTag = svgTag.replace(/viewBox="[^"]*"/, `viewBox="${finalViewBox}"`)
    } else {
      svgTag = svgTag.replace('>', ` viewBox="${finalViewBox}">`)
    }
  }

  // Add any additional attributes (rest props like style and role included)
  Object.entries({ ...rest, ...attributes }).forEach(([key, value]) => {
    if (!value) return
    if (svgTag.includes(`${key}=`)) {
      svgTag = svgTag.replace(new RegExp(`${key}="[^"]*"`), `${key}="${value}"`)
    } else {
      svgTag = svgTag.replace('>', ` ${key}="${value}">`)
    }
  })

  // Replace the original svg tag with the modified one
  return content.replace(/<svg[^>]*>/i, svgTag)
}

// Uses DOM Parser to modify the SVG.
// Likely not needed.
// Written by AI.
export function domParser(content, options) {
  const {
    class: className,
    width,
    height,
    attributes = {},
    transform,
    ...rest
  } = options

  // Parse SVG content
  const parser = new DOMParser()
  const doc = parser.parseFromString(content, 'image/svg+xml')
  const svgElement = doc.querySelector('svg')

  if (!svgElement) return content

  // Add class
  if (className) {
    const currentClass = svgElement.getAttribute('class') || ''
    svgElement.setAttribute(
      'class',
      currentClass ? `${currentClass} ${className}` : className,
    )
  }

  // Set dimensions
  if (width) svgElement.setAttribute('width', width)
  if (height) svgElement.setAttribute('height', height)

  // Add additional attributes (rest props like style and role included)
  Object.entries({ ...rest, ...attributes }).forEach(([key, value]) => {
    if (!value) return
    svgElement.setAttribute(key, value)
  })

  // Apply custom transform function
  if (typeof transform === 'function') {
    transform(svgElement)
  }

  // Return the modified SVG
  return svgElement.outerHTML
}
